namespace {

struct PulseCase {
    const char* name;
    int rate;
    double bpm;
    int accent;
    double drift;
};

constexpr PulseCase kCases[] = {
        {"steady80", 44100, 80, 1, 0},
        {"steady120", 44100, 120, 1, 0},
        {"steady174", 44100, 174, 1, 0},
        {"accented174", 44100, 174, 3, 0},
        {"steady120_48k", 48000, 120, 1, 0},
        {"drifting120", 44100, 120, 1, 0.10},
};

using ComparisonParam = std::tuple<int, bool, int>;
class BeatAnalysisComparisonTest : public MixxxTest,
                                   public testing::WithParamInterface<ComparisonParam> {};

TEST_P(BeatAnalysisComparisonTest, MeasuresGeneratedAudio) {
    const auto [plugin, fixed, caseIndex] = GetParam();
    const auto& test = kCases[caseIndex];
    constexpr int duration = 64;
    constexpr double origin = 0.2;
    const auto rate = mixxx::audio::SampleRate(test.rate);
    BeatDetectionSettings settings(config());
    settings.setBeatPluginId(AnalyzerBeats::availablePlugins().at(plugin).id());
    settings.setFixedTempoAssumption(fixed);
    auto track = Track::newTemporary();
    track->setAudioProperties(mixxx::audio::ChannelCount::stereo(),
            rate,
            mixxx::audio::Bitrate(),
            mixxx::Duration::fromSeconds(duration));
    AnalyzerBeats analyzer(config());
    ASSERT_TRUE(analyzer.initialize(AnalyzerTrack(track),
            rate,
            mixxx::audio::ChannelCount::stereo(),
            duration * test.rate));
    std::vector<CSAMPLE> audio(static_cast<size_t>(duration * test.rate) * 2);
    std::vector<double> truth;
    for (int beat = 0;; ++beat) {
        const double base = beat * 60 / test.bpm;
        const double time = origin + base + test.drift * base * base / (2 * duration);
        if (time >= duration) {
            break;
        }
        truth.push_back(time);
        const int start = static_cast<int>(std::lround(time * test.rate));
        const double amplitude = beat % test.accent ? 0.25 : 0.8;
        for (int i = 0; i < test.rate / 40 && start + i < duration * test.rate; ++i) {
            const double t = static_cast<double>(i) / test.rate;
            const auto value = static_cast<CSAMPLE>(
                    amplitude * std::exp(-180 * t) * std::cos(2 * M_PI * 110 * t));
            audio[2 * (start + i)] += value;
            audio[2 * (start + i) + 1] += value;
        }
    }
    for (size_t i = 0; i < audio.size(); i += 8192) {
        ASSERT_TRUE(analyzer.processSamples(
                audio.data() + i, std::min(size_t(8192), audio.size() - i)));
    }
    analyzer.storeResults(track);
    analyzer.cleanup();
    const auto grid = track->getBeats();
    ASSERT_TRUE(grid);
    ASSERT_TRUE(grid->getBpmInRange(mixxx::audio::kStartFramePos,
                            mixxx::audio::FramePos(duration * test.rate))
                    .isValid());
    double error = 0;
    int count = 0;
    for (double time : truth) {
        if (time < 4 || time > duration - 4) {
            continue;
        }
        const auto position = mixxx::audio::FramePos(time * test.rate);
        error += std::abs(grid->findClosestBeat(position) - position) / test.rate;
        ++count;
    }
    const QJsonObject metrics{{"case", test.name},
            {"plugin", plugin},
            {"fixed", fixed},
            {"constant", grid->hasConstantTempo()},
            {"bpm", track->getBpm()},
            {"mean_error_ms", 1000 * error / count}};
    RecordProperty("metrics", QJsonDocument(metrics).toJson(QJsonDocument::Compact).toStdString());
}

INSTANTIATE_TEST_SUITE_P(Backends,
        BeatAnalysisComparisonTest,
        testing::Combine(testing::Values(0, 1), testing::Bool(), testing::Range(0, 6)));

} // namespace
// End of autonomously generated AI-agent test.
